// test_foreach.rs - Test suite for foreach git processing
// Generated by step4_bootstrap - Foreach Git Processing

use split_decls_genesis::{
    foreach, git_subs, mkmods, extractmods, git_sub,
    get_all_git_repos, mkcrate, resolve_submodule_path, 
    find_cargo_tomls, extract_crate_name_from_cargo_toml,
    load_crate_source, extract_declarations, extract_names, CrateInfo
};

fn main() -> anyhow::Result<()> {
    println!("🧬 Testing foreach git processing system...");
    
    // Test git_subs! macro
    let all_repos = git_subs!();
    println!("✅ Found {} git repositories", all_repos.len());
    println!("📦 Sample repos: {:?}", &all_repos[..5.min(all_repos.len())]);
    
    // Test the full foreach pipeline on first few repos
    println!("\n🔄 Testing foreach pipeline...");
    let sample_repos = all_repos[..3.min(all_repos.len())].to_vec();
    
    let results = foreach!(gitrepo, sample_repos, {
        let git_sub_result = git_sub!(&gitrepo);
        let extracted_mods = extractmods!(git_sub_result);
        mkmods!(extracted_mods)
    });
    
    println!("\n📊 Pipeline results:");
    for (i, result) in results.iter().enumerate() {
        println!("  Repo {}: {} modules processed", i+1, result.len());
    }
    
    println!("\n🎉 Foreach git processing test complete!");
    Ok(())
}
